installLandscapeLayout();
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
let current=0,instrument='piano',mode='watch',stage=null,groups=[],step=0,request=0,busy=false,wanted=false,filter='all',chord='C',pianoHand='both',a=null,b=null,ab=false,showLabels=true,showPreview=true,effectsEnabled=true,zoom=1,camera='close',light=false,toastTimer,readoutKey='';
let computerKeyboard=null,keyboardEvents=[],showKeyboard=true,fretOffset=0,searchQuery='',composerFilter='',pendingIndex=null;
let favorites=[];try{favorites=JSON.parse(localStorage.getItem('nocturne-favorites')||'[]');if(!Array.isArray(favorites))favorites=[];}catch{}
const player=new PianoPlayer(()=>{if(mode==='watch'&&wanted){switchTrack(1,{gesture:false,keepSheet:true});return;}wanted=false;renderPlaying();});
const trackLoads=new Map();
function loadTrack(t){if(t.piano)return Promise.resolve(t);if(!trackLoads.has(t.id))trackLoads.set(t.id,(async()=>{const r=await fetch('./assets/music/'+t.id+'.json');if(!r.ok)throw new Error('曲谱加载失败，请再试一次');const d=await r.json();t.duration=d.duration;t.piano=annotatePiano(d.notes,t.id);return t;})().catch(e=>{trackLoads.delete(t.id);throw e;}));return trackLoads.get(t.id);}
const dataReady=loadTrack(catalog[0]).then(()=>{bindTrack();renderTracks();renderCurrent();}).catch(e=>{toast(e.message);$('#sound-status').hidden=false;throw e;});dataReady.catch(()=>{});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function score(){const t=catalog[current];if(!t.piano)return [];if(instrument==='piano')return t.piano;if(!t.guitar)t.guitar=arrangeForGuitar(t.piano);return t.guitar;}
function visibleNotes(){return player.notes.filter(n=>player.accepts(n));}
function rebuildGroups(){groups=groupNotes(visibleNotes());step=Math.max(0,Math.min(step,groups.length-1));if(stage){const notes=visibleNotes();if(notes.length)stage.setRange(Math.min(...notes.map(n=>n[1])),Math.max(...notes.map(n=>n[1])));}readoutKey='';}
function bindTrack(position=0){const t=catalog[current];if(!t.piano)return;player.setTrack({...t,notes:score()});player.setHand(instrument==='piano'&&!t.study?pianoHand:'both');if(position)player.seek(position);if(ab&&a!==null&&b!==null)player.setLoop([a,b]);rebuildGroups();}
function renderCurrent(){$('#track-title').textContent=catalog[current].title;$('#duration').textContent=format(catalog[current].duration||0);document.title=catalog[current].title+' · NOCTURNE';$('#stage').setAttribute('aria-label',(instrument==='piano'?'钢琴':'吉他')+'演奏与跟练');$('#scene').setAttribute('aria-label',instrument==='piano'?'放大的钢琴琴键，左手蓝绿，右手暖粉':'放大的吉他指板，显示实际弦与品位');$('#piano-hands').hidden=instrument==='guitar'||catalog[current].study;$('#guitar-preview-setting').hidden=instrument!=='guitar';$('#practice-note').textContent=catalog[current].study&&instrument==='piano'?'这是单旋律学习片段，只有右手旋律声部，可放慢速度逐组练习。':instrument==='piano'?'左右手颜色与演奏声部同步。逐组模式下，在此菜单用「上一组 / 下一组」选择音符，关闭菜单后看琴键示范。':'高亮圆点显示当前弦位，浅色圆环预告下一组。空弦为 0，品位与播放音高一致。';$('#arrangement-note').textContent=(catalog[current].version||'完整钢琴演奏')+(catalog[current].credit?' · 参考编配：'+catalog[current].credit:'');renderLegend();renderPlaying();renderTracks();}
function renderLegend(){const count=catalog[current].id==='cherry'?`${String(Math.min(37,Math.floor(Math.max(0,player.position()-.15)/(60/83*4))+1)).padStart(2,'0')} / 37`:'';$('#learning-status').innerHTML=instrument==='piano'?`<span class="hand-legend left-hand">左手</span><span class="hand-legend right-hand">右手</span><span class="bar-count" id="bar-count">${count}</span>`:`<span class="hand-legend right-hand">弦 · 品</span><span class="bar-count" id="bar-count">${count}</span>`;}
function renderPlaying(){syncKeyboardLabels();document.body.classList.toggle('free-mode',mode==='free');const performing=player.playing||(wanted&&busy);const waitingForSound=player.playing&&player.silent&&player.context?.state!=='running';document.body.classList.toggle('audio-blocked',waitingForSound);$('#sound-status').hidden=!waitingForSound||busy;document.body.classList.toggle('playing',player.playing);document.body.classList.toggle('guitar-mode',instrument==='guitar');$('#play').innerHTML=icon(performing?'pause':'play');$('#play').setAttribute('aria-label',mode==='step'?'试听当前音符组':performing?'暂停':'播放');$('#play').setAttribute('aria-busy',String(busy));$('#step-target').hidden=mode!=='step';const count=`${String(step+1).padStart(2,'0')} / ${groups.length}`;$('#step-target').textContent=count;$('#practice-group-count').textContent=count;}
function pause(){computerKeyboard?.clear();request++;pendingIndex=null;wanted=false;busy=false;player.pause();$('#loading').hidden=true;renderPlaying();}
async function requestFull(){try{const el=document.documentElement;const fn=el.requestFullscreen||el.webkitRequestFullscreen;if(fn&&!document.fullscreenElement)await fn.call(el,{navigationUI:'hide'});}catch{}await lockLandscape();}
function toggleFull(){try{if(document.fullscreenElement){document.exitFullscreen?.().catch?.(()=>{});}else requestFull();}catch{}}
async function start(gesture=false){
 if(pendingIndex!==null)pause();computerKeyboard?.clear();if(mode==='step'){audition();return;}if(gesture)requestFull();mode='watch';wanted=true;busy=true;const id=++request;$('#loading').hidden=false;$('#sound-status').hidden=true;renderPlaying();
 const pending=player.init(instrument);const visual=dataReady.then(()=>{if(id!==request||!wanted)return;if(!player.playing&&player.context?.state!=='running')player.startSilent();renderPlaying();});
 const blocked=setTimeout(()=>{if(id===request&&player.context?.state!=='running'){busy=false;$('#loading').hidden=true;$('#sound-status').hidden=false;renderPlaying();}},250);
 try{await Promise.all([pending,visual]);if(id!==request||!wanted)return;if(!player.playing||player.silent)player.start();$('#sound-status').hidden=true;busy=false;renderPlaying();}
 catch(e){if(id===request){busy=false;$('#sound-status').hidden=false;if(player.context?.state==='running'||!player.context){wanted=false;toast(e.message||'音色暂时无法加载，请点播放重试');}renderPlaying();}}
 finally{clearTimeout(blocked);if(id===request)$('#loading').hidden=true;}
}
// A normal interaction can satisfy browser autoplay policy; no separate start screen.
function unlockOnInteraction(e){if(pendingIndex!==null||!wanted||mode!=='watch'||player.context?.state==='running')return;if(e.type==='keydown'&&(e.isComposing||e.ctrlKey||e.metaKey||e.altKey))return;if(e.target.closest?.('#play,[data-instrument],[data-track],[data-mode],#free-start,#strum'))return;start(true);}
document.addEventListener('pointerup',unlockOnInteraction,true);document.addEventListener('click',unlockOnInteraction,true);document.addEventListener('keydown',unlockOnInteraction,true);
function togglePlay(){if(player.playing||wanted||busy){pause();return;}start(true);}
$('#play').addEventListener('click',togglePlay);$('#fullscreen').addEventListener('click',toggleFull);$('#fullscreen-setting').addEventListener('click',()=>{toggleFull();closeSheet();});
function selectInstrument(value){if(value===instrument)return;const resume=player.playing||wanted,pos=player.position();pause();instrument=value;player.setInstrument(value);bindTrack(pos);stage?.setInstrument(value);$$('[data-instrument]').forEach(el=>{const selected=el.dataset.instrument===value;el.classList.toggle('active',selected);el.setAttribute('aria-pressed',String(selected));});renderCurrent();if(mode==='step'){selectGroupAt(pos);return;}if(resume)start(true);}
$$('[data-instrument]').forEach(el=>el.addEventListener('click',()=>selectInstrument(el.dataset.instrument)));
async function selectTrack(index,{gesture=true,keepSheet=false}={}){
 if(!catalog[index]||!canPlayTrack(catalog[index]))return;
 pause();const id=request;pendingIndex=index;mode='watch';wanted=true;busy=true;$('#loading').hidden=false;renderMode();
 try{
  await Promise.all([dataReady,loadTrack(catalog[index])]);
  if(id!==request||pendingIndex!==index)return;
  // Commit the new selection only when its score is ready. Pause cancels the pending change.
  current=index;pendingIndex=null;a=null;b=null;ab=false;step=0;
  bindTrack();renderLoop();renderCurrent();renderMode();if(!keepSheet)closeSheet();start(gesture);
 }catch(e){if(id!==request)return;pendingIndex=null;wanted=false;busy=false;$('#loading').hidden=true;renderCurrent();toast(e.message);}
}
function renderTracks(){const tracks=catalog.filter(t=>(filter==='all'||(filter==='favorites'?favorites.includes(t.id):filter==='relax'?t.relax:t.category===filter))&&(!composerFilter||t.composer===composerFilter)&&(!searchQuery||(t.title+' '+t.artist+' '+(t.composerName||'')).toLowerCase().includes(searchQuery)));$('#track-list').innerHTML=tracks.length?tracks.map(t=>`<div class="track-row ${catalog[current]===t?'selected':''}"><button class="track-select" data-track="${t.id}" aria-label="播放${instrument==='piano'?'钢琴':'吉他'}${t.title}"><span class="track-index">${String(catalog.indexOf(t)+1).padStart(2,'0')}</span><span class="track-copy"><span class="track-name">${t.title}</span><span class="track-artist">${t.artist}</span>${t.version?`<span class="track-version">${t.version}</span>`:''}</span><span class="track-duration">${t.duration?format(t.duration):'—'}</span></button><button class="icon-button favorite ${favorites.includes(t.id)?'active':''}" data-favorite="${t.id}" aria-label="${favorites.includes(t.id)?'取消收藏':'收藏'}${t.title}" aria-pressed="${favorites.includes(t.id)}">${icon('heart')}</button></div>`).join(''):'<div class="empty-list">没有找到曲目。</div>';}
$('#track-search').addEventListener('input',e=>{searchQuery=e.target.value.trim().toLowerCase();renderTracks();});
const composers=[...new Map(catalog.filter(t=>t.composer).map(t=>[t.composer,t.composerName])).entries()];
$('#composer-filter').innerHTML='<option value="">全部作曲家</option>'+composers.map(([id,name])=>`<option value="${id}">${name}</option>`).join('');
$('#composer-filter').addEventListener('change',e=>{composerFilter=e.target.value;renderTracks();});
$('#track-list').addEventListener('click',e=>{const favorite=e.target.closest('[data-favorite]');if(favorite){const id=favorite.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('nocturne-favorites',JSON.stringify(favorites));}catch{}renderTracks();return;}const target=e.target.closest('[data-track]');if(target)selectTrack(catalog.findIndex(t=>t.id===target.dataset.track));});
$$('[data-filter]').forEach(el=>el.addEventListener('click',()=>{filter=el.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===el));renderTracks();}));

const titles={menu:'菜单',songs:'曲库',practice:'跟练',free:'自由弹奏',settings:'设置',info:'操作与音源',keyboard:'电脑键位',about:'关于 · 零基础入门'};
let sheetPage='menu',sheetHistory=[];
function openSheet(page='menu',goingBack=false){stage?.cancelInput();computerKeyboard?.clear();if(!$('#sheet').open)sheetHistory=[];else if(!goingBack&&page!==sheetPage)sheetHistory.push(sheetPage);sheetPage=page;$$('[data-page]').forEach(el=>el.hidden=el.dataset.page!==page);$('#sheet-title').textContent=titles[page];$('#sheet-back').hidden=page==='menu';$('#sheet-back').setAttribute('aria-label','返回'+titles[sheetHistory.at(-1)||'menu']);$('.sheet-content').scrollTop=0;if(!$('#sheet').open){$('#sheet').show();$('#sheet').setAttribute('aria-modal','true');$('#sheet-shade').hidden=false;$('#stage').inert=true;$('#sheet-close').focus();}else (page==='menu'?$('#sheet-close'):$('#sheet-back')).focus();}
function closeSheet(){$('#sheet').close();$('#sheet-shade').hidden=true;$('#stage').inert=false;$('#menu').focus();}
$('#sheet-shade').addEventListener('click',closeSheet);
function canFocusSheet(el){if(el.closest('[hidden]')||el.disabled)return false;for(let p=el.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open&&!p.querySelector('summary')?.contains(el))return false;return true;}
document.addEventListener('keydown',e=>{if(!$('#sheet').open)return;if(e.key==='Escape'){e.preventDefault();closeSheet();return;}if(e.key==='Tab'){const focusable=[...$('#sheet').querySelectorAll('button,input,a,summary,select')].filter(canFocusSheet);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#menu').addEventListener('click',()=>openSheet());$('#song-button').addEventListener('click',()=>openSheet('songs'));$('#speed-button').addEventListener('click',()=>openSheet('practice'));$('#sheet-close').addEventListener('click',closeSheet);$('#sheet-back').addEventListener('click',()=>openSheet(sheetHistory.pop()||'menu',true));$$('[data-open]').forEach(el=>el.addEventListener('click',()=>openSheet(el.dataset.open)));$('#sheet').addEventListener('click',e=>{if(e.target!==$('#sheet'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();});
function renderMode(){$$('[data-mode]').forEach(el=>{const chosen=el.dataset.mode===mode;el.classList.toggle('active',chosen);el.setAttribute('aria-pressed',String(chosen));});renderPlaying();}
function selectGroupAt(time){if(!groups.length)return;let index=groups.findIndex(g=>g.time>=time-.08);if(index===-1)index=groups.length-1;step=index;player.seek(groups[step].time+.001);readoutKey='';renderPlaying();}
function jumpGroup(direction){if(!groups.length)return;const playing=player.playing;if(mode==='step')step=Math.max(0,Math.min(groups.length-1,step+direction));else{const t=player.position();if(direction>0){const i=groups.findIndex(g=>g.time>t+.05);step=i===-1?groups.length-1:i;}else{let i=groups.findLastIndex(g=>g.time<t-.05);step=Math.max(0,i);}}player.seek(groups[step].time+.001);if(mode==='step')audition();else if(!playing)readoutKey='';renderPlaying();}
function switchTrack(direction,options){const from=pendingIndex??current;for(let offset=1;offset<=catalog.length;offset++){const index=(from+direction*offset+catalog.length)%catalog.length;if(canPlayTrack(catalog[index])){selectTrack(index,options);return;}}}
$('#next').addEventListener('click',()=>switchTrack(1));$('#previous').addEventListener('click',()=>switchTrack(-1));
function practiceGroup(direction){if(mode!=='step'){pause();mode='step';selectGroupAt(player.position());renderMode();}jumpGroup(direction);}
$('#next-group').addEventListener('click',()=>practiceGroup(1));$('#previous-group').addEventListener('click',()=>practiceGroup(-1));$('#audition-group').addEventListener('click',()=>practiceGroup(0));
$$('[data-mode]').forEach(el=>el.addEventListener('click',()=>{pause();mode=el.dataset.mode;if(mode==='step')selectGroupAt(player.position());renderMode();closeSheet();if(mode==='watch')start(true);}));
async function audition(){if(!groups.length)return;const id=++request;busy=true;renderPlaying();try{await player.init(instrument);if(id!==request)return;const group=groups[step];player.seek(group.time+.001);for(const n of group.notes){player.note(n[1],player.context.currentTime+(n[0]-group.time)/player.rate,Math.min(1.8,n[2]/player.rate),n[3],{string:instrument==='guitar'?n[4]:null});stage?.press(n);}$('#sound-status').hidden=true;}catch(e){toast(e.message);}finally{if(id===request){busy=false;renderPlaying();}}}
$$('[data-rate]').forEach(el=>el.addEventListener('click',()=>{computerKeyboard?.clear();player.setRate(Number(el.dataset.rate));$$('[data-rate]').forEach(x=>x.classList.toggle('active',x===el));const text=player.rate+'×';$('#rate-output').textContent=text;$('#speed-button').textContent=text;}));
$$('[data-hand]').forEach(el=>el.addEventListener('click',()=>{computerKeyboard?.clear();pianoHand=el.dataset.hand;player.setHand(instrument==='piano'?pianoHand:'both');$$('[data-hand]').forEach(x=>x.classList.toggle('active',x===el));rebuildGroups();if(mode==='step')selectGroupAt(player.position());}));
function renderLoop(){$('#a-time').textContent=a===null?'—':format(a);$('#b-time').textContent=b===null?'—':format(b);$('#ab-toggle').classList.toggle('active',ab);$('#ab-toggle').setAttribute('aria-pressed',String(ab));const z=$('#loop-zone');z.style.left=(a||0)/Math.max(1,player.duration)*100+'%';z.style.width=ab&&a!==null&&b!==null?(b-a)/player.duration*100+'%':'0%';}
$('#mark-a').addEventListener('click',()=>{a=player.position();if(b!==null&&b<=a+.2)b=null;ab=false;player.setLoop(null);renderLoop();});$('#mark-b').addEventListener('click',()=>{if(a===null)a=0;const end=player.position();if(end<=a+.2){toast('先向后播放一段，再标记 B');return;}b=end;ab=true;player.setLoop([a,b]);renderLoop();});$('#ab-toggle').addEventListener('click',()=>{if(a===null||b===null){toast('先标记起点 A 和终点 B');return;}ab=!ab;player.setLoop(ab?[a,b]:null);renderLoop();});$('#clear-loop').addEventListener('click',()=>{a=null;b=null;ab=false;player.setLoop(null);renderLoop();});
function switchButton(el,value){el.classList.toggle('on',value);el.setAttribute('aria-checked',String(value));}
function renderPlaybackMode(){const button=$('#playback-mode'),label=player.repeat?'单曲循环':'顺序播放',next=player.repeat?'顺序播放':'单曲循环';button.innerHTML=icon(player.repeat?'repeat-one':'sequence')+'<span>'+(player.repeat?'单曲':'顺序')+'</span>';button.dataset.playback=player.repeat?'single':'sequence';button.setAttribute('aria-pressed',String(player.repeat));button.setAttribute('aria-label','播放方式：'+label+'，点击切换为'+next);button.title=label+' · 点击切换为'+next;}
$('#playback-mode').addEventListener('click',()=>{player.repeat=!player.repeat;renderPlaybackMode();});$('#metronome').addEventListener('click',()=>{player.metronome=!player.metronome;switchButton($('#metronome'),player.metronome);});
$('#progress').addEventListener('input',e=>{computerKeyboard?.clear();player.seek(Number(e.target.value)/100*player.duration);if(mode==='step')selectGroupAt(player.position());readoutKey='';});
$('#volume').addEventListener('input',e=>{player.setVolume(Number(e.target.value)/100);$('#volume-output').textContent=e.target.value+'%';e.target.style.setProperty('--fill',e.target.value+'%');});$('#volume').style.setProperty('--fill','65%');
$$('[data-camera]').forEach(el=>el.addEventListener('click',()=>{camera=el.dataset.camera;stage?.setCamera(camera);$$('[data-camera]').forEach(x=>x.classList.toggle('active',x===el));}));$('#zoom').addEventListener('input',e=>{zoom=Number(e.target.value);stage?.setZoom(zoom);$('#zoom-output').textContent=zoom+'×';});
$('#effects-toggle').addEventListener('click',()=>{effectsEnabled=!effectsEnabled;stage?.setEffects(effectsEnabled);switchButton($('#effects-toggle'),effectsEnabled);});
$('#labels-toggle').addEventListener('click',()=>{showLabels=!showLabels;stage?.setLabels(showLabels);switchButton($('#labels-toggle'),showLabels);});$('#preview-toggle').addEventListener('click',()=>{showPreview=!showPreview;stage?.setPreview(showPreview);switchButton($('#preview-toggle'),showPreview);});function toggleTheme(){light=!light;renderTheme();}
function renderTheme(){document.body.classList.toggle('light',light);stage?.setTheme(light);switchButton($('#theme'),light);const button=$('#theme-toggle'),label=light?'切换为黑夜主题':'切换为白天主题';button.innerHTML=icon(light?'moon':'sun');button.setAttribute('aria-pressed',String(light));button.setAttribute('aria-label',label);button.title=label;document.querySelector('meta[name="theme-color"]').content=light?'#d9d8d2':'#0c0e12';}
$('#theme').addEventListener('click',toggleTheme);$('#theme-toggle').addEventListener('click',toggleTheme);
let manualAttackTime=0;
function prepareManualInput(warm=true){
 if(player.playing||busy||wanted||!['free','step'].includes(mode)){pause();manualAttackTime=0;}
 else if(keyboardEvents.length)computerKeyboard?.clear();
 if(mode!=='step')mode='free';renderPlaying();
 // Begin audio unlock/sample loading on contact so release can sound promptly.
 if(warm)player.init(instrument).catch(()=>{});
}
async function manualInput(hit){
 prepareManualInput(false);const id=request,selected=instrument,velocity=Math.max(.3,Math.min(1,hit.velocity??.78));
 const n=selected==='guitar'?[0,hit.midi,1.5,velocity,hit.string,hit.fret,'R']:[0,hit.midi,.8,velocity,hit.midi<60?'L':'R'];
 n._pluck={x:hit.x,direction:hit.direction,velocity};stage?.press(n);
 try{
  await player.init(selected);if(id!==request||selected!==instrument)return;
  const now=player.context.currentTime,when=selected==='guitar'?Math.max(now,Math.min(manualAttackTime+.009,now+.12)):now;
  manualAttackTime=when;player.note(hit.midi,when,n[2],velocity,{string:hit.string});$('#sound-status').hidden=true;renderPlaying();
 }catch(e){toast(e.message);}
}
$$('[data-chord]').forEach(el=>el.addEventListener('click',()=>{chord=el.dataset.chord;$$('[data-chord]').forEach(x=>x.classList.toggle('active',x===el));}));$('#strum').addEventListener('click',async()=>{if(instrument!=='guitar')selectInstrument('guitar');pause();mode='free';const id=request;try{await player.init('guitar');if(id!==request)return;const shape=chordShapes[chord];player.strum(shape);shape.forEach((m,s)=>{if(m!==null)setTimeout(()=>{if(instrument==='guitar'&&id===request)stage?.press([0,m,1,.7,s,m-openStrings[s],'R']);},s*35);});closeSheet();renderMode();}catch(e){toast(e.message);}});$('#free-start').addEventListener('click',()=>{pause();mode='free';renderMode();closeSheet();});
function readout(events,preview){const showKeys=keyboardHintsActive(),current=events.length?events:preview;const key=instrument+showKeys+fretOffset+current.map(n=>n[1]+':'+n[4]+':'+n[5]).join(',');if(key===readoutKey)return;readoutKey=key;if(instrument==='piano'){$('#note-readout').innerHTML=['L','R'].map(hand=>{const names=[...new Set(current.filter(n=>handOf(n,'piano')===hand).map(n=>noteName(n[1])+(showKeys&&pianoKeyLabel(n[1])?' ['+pianoKeyLabel(n[1])+']':'')))];return names.length?`<span class="readout-hand ${hand==='L'?'left':''}"><small>${hand==='L'?'左':'右'}</small><b>${names.join(' · ')}</b></span>`:'';}).join('');}else $('#note-readout').innerHTML=current.map(n=>`<span class="readout-hand"><b>${6-n[4]}弦 ${n[5]}品</b><small>${noteName(n[1])}${showKeys?' · '+(guitarKeyLabel(n[4],n[5],fretOffset)||'调整品位起点'):''}</small></span>`).join('');}
let lastBar='';function update(){const time=player.position();$('#elapsed').textContent=format(time);if(document.activeElement!==$('#progress'))$('#progress').value=player.duration?time/player.duration*100:0;$('#progress').style.setProperty('--fill',(player.duration?time/player.duration*100:0)+'%');const active=mode==='step'?(groups[step]?.notes||[]):mode==='free'?[]:player.eventsAt(time);const index=groups.findIndex(g=>g.time>time+.06);const next=index>=0?groups[index].notes:[];stage?.setFrame({active,next:mode==='free'?[]:next});readout(keyboardEvents.length?keyboardEvents:active,mode==='free'?[]:next);const bar=catalog[current].id==='cherry'?String(Math.min(37,Math.floor(Math.max(0,time-.15)/(60/83*4))+1)).padStart(2,'0')+' / 37':'';if(bar!==lastBar){lastBar=bar;if($('#bar-count'))$('#bar-count').textContent=bar;}}
setInterval(update,33);
$('#credits').innerHTML='钢琴：<a href="https://sfzinstruments.github.io/pianos/salamander/" target="_blank" rel="noopener">Salamander · Alexander Holm</a> / <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a><br>吉他：<a href="https://github.com/nbrosowsky/tonejs-instruments" target="_blank" rel="noopener">University of Iowa / Nicholas Brosowsky · CC BY 3.0</a><br>视觉材质：<a href="https://polyhaven.com/a/wood_table_001" target="_blank" rel="noopener">Poly Haven · Wood Table 001</a>（Dimitrios Savva / Rico Cilliers）、<a href="https://polyhaven.com/a/studio_small_09" target="_blank" rel="noopener">Studio Small 09</a>（Sergej Majboroda） / <a href="https://polyhaven.com/license" target="_blank" rel="noopener">CC0</a><br>曲谱：'+catalog.filter(canPlayTrack).map(t=>`<a href="${t.source}" target="_blank" rel="noopener">${t.title}</a>${t.credit?'（'+t.credit+'）':''}${t.license?` · <a href="${t.licenseUrl||t.source}" target="_blank" rel="noopener">${t.license}</a>`:''}`).join('<br>');
import('./scene.js').then(({createLearningStage})=>{stage=createLearningStage($('#scene'),$('#labels'),manualInput,prepareManualInput);stage.setInstrument(instrument);stage.setHeld(keyboardEvents);syncKeyboardLabels();stage.setLabels(showLabels);stage.setPreview(showPreview);stage.setEffects(effectsEnabled);stage.setTheme(light);stage.setCamera(camera);stage.setZoom(zoom);rebuildGroups();}).catch(()=>{toast('演奏画面加载失败，请刷新页面');});
function keyboardHintsActive(){return mode==='free'&&showKeyboard;}
function syncKeyboardLabels(){stage?.setKeyboard({enabled:keyboardHintsActive(),piano:pianoKeyLabel,guitar:(string,fret)=>guitarKeyLabel(string,fret,fretOffset)});readoutKey='';}
function renderKeyboardMenu(){
 $('#keyboard-piano-map').innerHTML=Array.from({length:5},(_,o)=>`<div class="keymap-octave">${pianoBindings.filter(b=>!b.shift&&b.midi>=36+o*12&&b.midi<48+o*12).map(b=>`<div><small>${noteName(b.midi)}</small><kbd>${b.label}</kbd>${pianoKeyLabel(b.midi+1).startsWith('⇧')?`<small>${noteName(b.midi+1)}</small><kbd class="sharp">${pianoKeyLabel(b.midi+1)}</kbd>`:''}</div>`).join('')}</div>`).join('')+'<p class="setting-note">C7 → m；⇧ 表示按住 Shift。字母谱中的大写字母和数字符号对应黑键，例如 T = ⇧t、! = ⇧1。</p>';
 $('#keyboard-guitar-map').innerHTML=guitarRows.map(r=>`<div class="keymap-string"><b>${6-r.string}弦 <small>${noteName(openStrings[r.string])}</small></b><code>${r.shift?'⇧ + ':''}${[...r.keys].join(' ')}</code><small>${fretOffset}–${fretOffset+r.keys.length-1} 品，向右逐品递增</small></div>`).join('');
 $('#fret-offset').textContent=fretOffset+' 品';$('#fret-lower').disabled=fretOffset===0;$('#fret-higher').disabled=fretOffset===3;switchButton($('#keyboard-labels'),showKeyboard);
}
function shiftFrets(delta){computerKeyboard?.clear();fretOffset=Math.max(0,Math.min(3,fretOffset+delta));syncKeyboardLabels();renderKeyboardMenu();toast('吉他键位起点：'+fretOffset+' 品');}
$('#fret-lower').addEventListener('click',()=>shiftFrets(-1));$('#fret-higher').addEventListener('click',()=>shiftFrets(1));$('#keyboard-labels').addEventListener('click',()=>{showKeyboard=!showKeyboard;syncKeyboardLabels();renderKeyboardMenu();});
computerKeyboard=installComputerKeyboard({instrument:()=>instrument,offset:()=>fretOffset,blocked:()=>$('#sheet').open,
 onPrepare(){if(player.playing||busy||wanted)pause();if(mode!=='step')mode='free';renderPlaying();},
 onUsed(){},
 async onPress(hit,entry){const selected=instrument;try{await player.init(selected);if(entry.released||instrument!==selected)return;$('#sound-status').hidden=true;stage?.ensurePitch(hit.midi);return player.note(hit.midi,player.context.currentTime,30,.78,{string:hit.string});}catch(e){toast(e.message);throw e;}},
 onRelease(voice){player.release(voice);},onChange(events){keyboardEvents=events;stage?.setHeld(events);readoutKey='';}
});
document.addEventListener('keydown',e=>{if(e.isComposing||e.keyCode===229||e.ctrlKey||e.metaKey||e.altKey||editableTarget(e.target)||$('#sheet').open)return;if(e.code==='Space'){if(e.target.closest?.('button,a,[role="button"]'))return;e.preventDefault();if(!e.repeat)togglePlay();}if(e.code==='ArrowRight'){e.preventDefault();if(!e.repeat){computerKeyboard.clear();switchTrack(1);}}if(e.code==='ArrowLeft'){e.preventDefault();if(!e.repeat){computerKeyboard.clear();switchTrack(-1);}}if(instrument==='guitar'&&['PageUp','PageDown'].includes(e.code)){e.preventDefault();if(!e.repeat)shiftFrets(e.code==='PageUp'?1:-1);}});
renderKeyboardMenu();
if('mediaSession'in navigator){for(const [action,fn] of Object.entries({play:()=>start(),pause,previoustrack:()=>switchTrack(-1),nexttrack:()=>switchTrack(1),seekbackward:()=>player.seek(player.position()-5),seekforward:()=>player.seek(player.position()+5),seekto:e=>player.seek(e.seekTime)}))try{navigator.mediaSession.setActionHandler(action,fn);}catch{}}
document.addEventListener('fullscreenchange',()=>{const label=document.fullscreenElement?'退出系统全屏':'进入系统全屏';$('#fullscreen').setAttribute('aria-label',label);$('#fullscreen-setting').textContent=label;});
renderTracks();renderCurrent();renderPlaybackMode();renderTheme();requestFull();start(false);
